fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n);
    assert_eq!(conds_1.len(), n);
    assert_eq!(conds_2.len(), n);

    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        // By problem statement: at least one of conds_1[i], conds_2[i] is true
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        let v1 = vals_1[i];
        let v2 = vals_2[i];

        let val = match (c1, c2) {
            (true, true) => (v1 + v2) / 2,
            (true, false) => v1,
            (false, true) => v2,
            (false, false) => unreachable!("At least one boolean at i must be true"),
        };

        avgs.push(val);
    }
}